  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills tiles with water up to the specified distance from the source.
   * Algorithm: 
   * 1. If this is the first call (prevFilledDistance == null), call fillBeginTile() to mark source as filled and initialize prevFilledTiles and filledTiles.
   * 2. For each new distance value from prevFilledDistance+1 to distance:
   *    a. For each coordinate in filledTiles at the previous distance level, check all four directions.
   *    b. For each direction, get the adjacent cell coordinate.
   *    c. If adjacent cell is a FillableCell with a pipe that is not filled:
   *       - Check if current cell's pipe connects in that direction AND adjacent pipe connects in the opposite direction.
   *       - If both connect, mark adjacent pipe as filled and add to filledTiles list.
   * 3. Update prevFilledDistance to distance.
   * Related Features: filledTiles, prevFilledDistance, prevFilledTiles, sourceCell fields; cell grid
   * Related Classes: Coordinate, FillableCell, Pipe, TerminationCell, Direction, Pa19Helper
   * Input: distance : int - the maximum distance to fill (positive integer)
   * Output: void
   * Pre-condition: distance >= 0; sourceCell is initialized; water flow has started (delayBar countdown has passed zero)
   * Post-condition: All reachable pipes within the given distance from source are marked as filled; filledTiles updated accordingly.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    // 1. If this is the first call (prevFilledDistance == null), call fillBeginTile()
    if (getPrevFilledDistance() == null) {
      fillBeginTile();
      setPrevFilledDistance(0);
    }

    // 2. For each new distance value from prevFilledDistance+1 to distance
    int startIdx = 0;
    for (int d = getPrevFilledDistance() + 1; d <= distance; d++) {
      int endIdx = getFilledTiles().size();

      // For each coordinate in filledTiles at the previous distance level
      for (int i = startIdx; i < endIdx; i++) {
        Coordinate coord = getFilledTiles().get(i);
        Cell currentCell = getCell()[coord.getRow()][coord.getCol()];

        // Check all four directions
        for (Direction dir : Direction.VALUES) {
          // Get adjacent cell coordinate
          Coordinate offset = Pa19Factory.eINSTANCE.createPa19Helper().getOffset(dir);
          Coordinate adjCoord = coord.add(offset);

          // Check bounds
          int adjRow = adjCoord.getRow();
          int adjCol = adjCoord.getCol();
          if (adjRow < 0 || adjRow >= getRows() || adjCol < 0 || adjCol >= getCols()) {
            continue;
          }

          Cell adjCell = getCell()[adjRow][adjCol];
          // If adjacent cell is a FillableCell with a pipe that is not filled
          if (adjCell instanceof FillableCell) {
            FillableCell fillableAdj = (FillableCell) adjCell;
            Pipe adjPipe = fillableAdj.getPipe();
            if (adjPipe != null && !adjPipe.isFilled()) {
              // Check if current cell's pipe connects in that direction
              boolean currentConnects = false;
              if (currentCell instanceof FillableCell) {
                Pipe curPipe = ((FillableCell) currentCell).getPipe();
                if (curPipe != null && curPipe.getConnections().contains(dir)) {
                  currentConnects = true;
                }
              } else if (currentCell instanceof TerminationCell) {
                if (((TerminationCell) currentCell).getPointingTo() == dir) {
                  currentConnects = true;
                }
              }

              // Check if adjacent pipe connects in the opposite direction
              if (currentConnects) {
                Direction opposite = Pa19Factory.eINSTANCE.createPa19Helper().getOpposite(dir);
                if (adjPipe.getConnections().contains(opposite)) {
                  adjPipe.setFilled(true);
                  getFilledTiles().add(adjCoord);
                }
              }
            }
          }
        }
      }
      startIdx = endIdx;
    }

    // 3. Update prevFilledDistance to distance
    setPrevFilledDistance(distance);
  }

